{"concepts":[{"oldConceptId":"ce:BackupAndRecovery","split":true,"newConcepts":[{"conceptId":"ce:Backup","block":"ce:Backup a tbox:ConceptualEntity ;
    rdfs:label "Backup"@en ;
    rdfs:comment "An operations and maintenance activity that creates a copy of data or system state so that it can be restored later."@en ;
    rdfs:subClassOf ce:OperationsAndMaintenanceActivity ;
    foaf:page <https://en.wikipedia.org/wiki/Backup> ."},{"conceptId":"ce:Recovery","block":"ce:Recovery a tbox:ConceptualEntity ;
